import{_ as c,o as d,a as t,b as o}from"./app.C41L12d5.js";const a="/ascendc.github.io/assets/reduce_decision_tree.CX3R28RE.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"归约计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/reduction_compute/reduction_compute"},{"text":"概述","link":"/api/SIMD-API/basic_api/memory_vector_compute/reduction_compute/Introduction"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/reduction_compute/Introduction.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/reduction_compute/Introduction.md","lastUpdated":1787050286000}'),l={name:"api/SIMD-API/basic_api/memory_vector_compute/reduction_compute/Introduction.md"};function i(u,e,r,p,R,n){return d(),t("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>归约计算概述</h1><p><strong>表1</strong> 归约计算接口与主要功能</p><table><thead><tr><th>接口</th><th>主要功能</th><th>输出长度</th></tr></thead><tbody><tr><td><a href="./ReduceDataBlock.html">ReduceDataBlock</a></td><td>对每个DataBlock内的数据求和/求最大值/求最小值。</td><td>1 element / DataBlock</td></tr><tr><td><a href="./ReduceRepeat.html">ReduceRepeat</a></td><td>对每个repeat内的数据求和/求最大值/求最小值。<br>其中求最大值或最小值时可选择输出对应的索引。</td><td>求和：1 element / repeat；<br>求最大值/最小值：1 element (1 index) / repeat。</td></tr><tr><td><a href="./ReducePairElem.html">ReducePairElem</a></td><td>对相邻两个元素进行求和。</td><td>1 element / pair</td></tr><tr><td><a href="./ReduceSum.html">ReduceSum</a></td><td>对所有输入数据求和。</td><td>1 element</td></tr><tr><td><a href="./ReduceMax.html">ReduceMax</a>/<a href="./ReduceMin.html">ReduceMin</a></td><td>对所有输入数据求最大值/最小值。<br>可选择输出对应的索引。</td><td>1 element (1 index)</td></tr><tr><td><a href="../reduction_compute_aux_config/GetReduceRepeatSumSpr_ISASI.html">GetReduceRepeatSumSpr(ISASI)</a></td><td>获取<code>ReduceSum</code>接口的计算结果。</td><td>1 element</td></tr><tr><td><a href="../reduction_compute_aux_config/GetReduceRepeatMaxMinSpr_ISASI.html">GetReduceRepeatMaxMinSpr(ISASI)</a></td><td>获取调用<code>ReduceRepeat&lt;MAX/MIN&gt;</code>时所有repeat内的最值及其索引，或获取调用<code>ReduceMax</code>、<code>ReduceMin</code>得到的最值。</td><td>1 element (1 index)</td></tr></tbody></table><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，Memory矢量计算的归约计算接口底层均通过VF调用转换为Reg矢量计算指令执行，接口内部存在额外的VF调用开销和Unified Buffer（UB）中转（如sharedTmpBuffer）。因此Memory API不保证极致性能，对性能敏感的场景建议直接使用Reg矢量计算中的<a href="../../reg_vector_compute/reduction_compute/reduction_compute.html">归约计算</a>（Reg::Reduce、Reg::PairReduceElem、Reg::ReduceDataBlock）。</p></div><div data-filter="A3,910b"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品、Atlas A2 训练系列产品/Atlas A2 推理系列产品，在使用归约计算接口时，有如下使用建议。</p><ul><li><p><code>ReduceDataBlock</code></p><ul><li><strong>推荐使用场景</strong>： <ul><li>数据类型为<code>float</code>时：相比<code>ReduceRepeat</code>有更高的理论并行度；与<code>ReducePairElem</code>拥有相同的理论并行度，但可以归约更多数据。</li><li>数据类型为<code>half</code>、数据量小于等于一个DataBlock时：<code>ReduceDataBlock</code>与<code>ReduceRepeat</code>具有相同的理论并行度，但<code>ReduceDataBlock</code>支持只对一个DataBlock进行归约，而<code>ReduceRepeat</code>需要对八个DataBlock（一个repeat）进行归约，因此<code>ReduceDataBlock</code>效率更高。 <ul><li>示例：当数据长度为2K时，可以先进行一次<code>ReduceRepeat</code>归约得到长度为16（32字节），再进行一次<code>ReduceDataBlock</code>即可。此时一次<code>ReduceRepeat</code>+一次<code>ReduceDataBlock</code>耗时比两次<code>ReduceRepeat</code>短。</li></ul></li></ul></li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>ReduceRepeat</code></p><ul><li><strong>推荐使用场景</strong>： <ul><li>需要获取最值的索引且对性能敏感的场景。</li><li>数据类型为<code>half</code>、数据量大于一个DataBlock时：<code>ReduceRepeat</code>与<code>ReduceDataBlock</code>具有相同的理论并行度，但<code>ReduceRepeat</code>能一次调用对八个DataBlock（一个repeat）进行归约，而使用<code>ReduceDataBlock</code>至少需要调用两次，因此<code>ReduceRepeat</code>耗时更短。</li></ul></li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>ReducePairElem</code></p><ul><li><strong>推荐使用场景</strong>： <ul><li>适合在需要对相邻两个元素进行求和操作时使用。</li><li>数据类型为<code>half</code>时，<code>ReducePairElem</code>的理论并行度是归约指令中最高的，因此在数据量较大、需要多次调用<code>ReduceDataBlock</code>及<code>ReduceRepeat</code>时，适合用于对数据进行初步归约。</li></ul></li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>ReduceSum</code></p><ul><li><strong>推荐使用场景</strong>： <ul><li>该接口内部通过软件仿真实现，性能可能不及硬件指令实现的<code>ReduceDataBlock</code>和<code>ReduceRepeat</code>接口，不推荐对性能敏感的场景使用。</li><li>该接口能通过一次调用得到归约结果，且支持更长的输入数据，适合用于需要快速验证实现的场景。</li></ul></li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>ReduceMax</code>/<code>ReduceMin</code></p><ul><li><strong>推荐使用场景</strong>： <ul><li>该接口内部通过软件仿真实现，性能可能不及硬件指令实现的<code>ReduceDataBlock</code>和<code>ReduceRepeat</code>接口，不推荐对性能敏感的场景使用。</li><li>该接口能通过一次调用得到归约结果，且支持更长的输入数据，适合用于需要快速验证实现的场景。</li></ul></li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>GetReduceRepeatSumSpr</code></p><ul><li><strong>推荐使用场景</strong>：获取tensor前n个数据计算场景的<code>ReduceSum</code>结果。</li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li><li><p><code>GetReduceRepeatMaxMinSpr</code></p><ul><li><strong>推荐使用场景</strong>：获取连续计算场景的<code>ReduceRepeat&lt;MAX/MIN&gt;</code>所有repeat内的最值及其索引，或获取连续计算场景的<code>ReduceMax</code>/<code>ReduceMin</code>得到的最值。</li><li>支持的数据类型：<code>half</code>、<code>float</code></li></ul></li></ul><p>归约接口的选择可以参考如下<a href="#fig1">决策树</a>：</p><p><a id="fig1"></a></p><p><strong>图1</strong> 归约接口选择决策树</p><p><img src="'+a+'" alt="归约接口选择决策树" title="归约接口选择决策树"></p><p>注：在数据类型为<code>half</code>时，<code>ReduceDataBlock</code>及<code>ReduceRepeat</code>接口并行度不如<code>ReducePairElem</code>及基础算术接口<a href="../basic_arithmetic/Add.html">Add</a>，<a href="../basic_arithmetic/Max.html">Max</a>，<a href="../basic_arithmetic/Min.html">Min</a>。在数据量较大，需要多次调用<code>ReduceDataBlock</code>及<code>ReduceRepeat</code>时，可以考虑使用<code>ReducePairElem</code>或基础算术接口对数据进行初步归约后再调用归约计算接口。</p></div></article></div>',1)])])}const s=c(l,[["render",i]]);export{_ as __pageData,s as default};
